package com.primehr.evidence.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="evidence_corrective_action")public class EvidenceCorrectiveAction extends RspAuditedEntity{public enum Status{PLANNED,IN_PROGRESS,SUBMITTED_FOR_VERIFICATION,VERIFIED,RETURNED,CANCELLED}@Column(name="gap_id",nullable=false,length=36)private String gapId;@Column(name="assessment_case_id",nullable=false,length=36)private String assessmentCaseId;@Column(nullable=false,length=3000)private String actionPlan;@Column(name="responsible_employee_no",nullable=false,length=100)private String responsibleEmployeeNo;@Column(name="responsible_name",nullable=false,length=250)private String responsibleName;@Column(name="target_date",nullable=false)private LocalDate targetDate;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private Status status;@Column(name="progress_note",length=3000)private String progressNote;@Column(name="completion_evidence_reference",length=1000)private String completionEvidenceReference;@Column(name="submitted_by",length=100)private String submittedBy;@Column(name="submitted_at")private Instant submittedAt;@Column(name="verified_by",length=100)private String verifiedBy;@Column(name="verified_at")private Instant verifiedAt;@Column(name="decision_reason",length=3000)private String decisionReason;protected EvidenceCorrectiveAction(){}public EvidenceCorrectiveAction(String a,String gap,String c,String plan,String employee,String name,LocalDate target){super(a);gapId=requiredText(gap,"gapId");assessmentCaseId=requiredText(c,"assessmentCaseId");actionPlan=requiredText(plan,"actionPlan");responsibleEmployeeNo=requiredText(employee,"responsibleEmployeeNo");responsibleName=requiredText(name,"responsibleName");targetDate=java.util.Objects.requireNonNull(target);status=Status.PLANNED;}public void update(String plan,LocalDate target,String progress){if(status==Status.VERIFIED||status==Status.CANCELLED||status==Status.SUBMITTED_FOR_VERIFICATION)throw new IllegalStateException("Corrective action cannot be edited in its current status");actionPlan=requiredText(plan,"actionPlan");targetDate=java.util.Objects.requireNonNull(target);progressNote=optionalText(progress);}public void start(String actor,String progress){if(status!=Status.PLANNED&&status!=Status.RETURNED)throw new IllegalStateException("Corrective action is not ready to start");if(!responsibleEmployeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("Only the responsible employee may start the action");status=Status.IN_PROGRESS;progressNote=requiredText(progress,"progressNote");}public void submit(String actor,String progress,String evidence,Instant at){if(status!=Status.IN_PROGRESS&&status!=Status.RETURNED)throw new IllegalStateException("Corrective action is not ready for verification");if(!responsibleEmployeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("Only the responsible employee may submit the action");progressNote=requiredText(progress,"progressNote");completionEvidenceReference=requiredText(evidence,"completionEvidenceReference");submittedBy=actor;submittedAt=at;status=Status.SUBMITTED_FOR_VERIFICATION;}public void verify(String actor,String reason,Instant at){if(status!=Status.SUBMITTED_FOR_VERIFICATION)throw new IllegalStateException("Corrective action is not awaiting verification");verifiedBy=requiredText(actor,"actor");verifiedAt=at;decisionReason=requiredText(reason,"reason");status=Status.VERIFIED;}public void returnForRework(String actor,String reason){if(status!=Status.SUBMITTED_FOR_VERIFICATION)throw new IllegalStateException("Corrective action is not awaiting verification");decisionReason=requiredText(reason,"reason");verifiedBy=requiredText(actor,"actor");status=Status.RETURNED;}public void cancel(String actor,String reason){if(status==Status.VERIFIED||status==Status.CANCELLED)throw new IllegalStateException("Corrective action cannot be cancelled");verifiedBy=requiredText(actor,"actor");decisionReason=requiredText(reason,"reason");status=Status.CANCELLED;}public String getGapId(){return gapId;}public String getAssessmentCaseId(){return assessmentCaseId;}public String getActionPlan(){return actionPlan;}public String getResponsibleEmployeeNo(){return responsibleEmployeeNo;}public String getResponsibleName(){return responsibleName;}public LocalDate getTargetDate(){return targetDate;}public Status getStatus(){return status;}public String getProgressNote(){return progressNote;}public String getCompletionEvidenceReference(){return completionEvidenceReference;}public String getSubmittedBy(){return submittedBy;}public Instant getSubmittedAt(){return submittedAt;}public String getVerifiedBy(){return verifiedBy;}public Instant getVerifiedAt(){return verifiedAt;}public String getDecisionReason(){return decisionReason;}}
